public class SpawnEntityCommand : Command
{
    private static readonly Argument<string> Entity = new("entity", "Entity to spawn");
    private static readonly Option<int> Count = new("count", "How many to spawn", 1, "c");

    public SpawnEntityCommand() : base("entity", "Spawns an entity into the active scene")
    {
        Accepts(Entity, Count);
    }

    public override ICommandOutput Invoke(ICommandInput input)
    {
        return CommandOutput.Success($"Spawned {input.GetValue<int>(Count)}x {input.GetValue<string>(Entity)}");
    }
}

public class SpawnCommand : CommandGroup
{
    public SpawnCommand() : base("spawn", "Spawns things into the active scene")
    {
        Add(new SpawnEntityCommand());
        Add(new SpawnItemCommand());
    }
}

private static readonly Argument<int> Percent = new("percent", "Share of the health to restore")
{
    Parser = text => int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value) && value is >= 0 and <= 100
        ? ParsedValue<int>.Read(value)
        : ParsedValue<int>.Refused($"The share has to be a whole number between 0 and 100, and '{text}' is not.")
};

private static readonly Argument<int> Count = new("count", "How many to summon", 1)
{
    Validator = count => count is >= 1 and <= 10 ? null : $"Between 1 and 10 can be summoned at once, not {count}."
};
